const getStudentsWithOutstandingFees = `-- name: GetStudentsWithOutstandingFees :many
SELECT
    u.id AS user_id,
    s.id AS student_id,
    u.name,
    u.email,
    COALESCE(fees.total_fee, 0)::BIGINT AS total_course_fee,
    COALESCE(pays.total_paid, 0)::BIGINT AS total_paid,
    COALESCE(discounts.total_discount, 0)::BIGINT AS total_discount,
    COALESCE(scholarships.total_scholarship, 0)::BIGINT AS total_scholarship,
    (
        COALESCE(fees.total_fee, 0)
        - COALESCE(pays.total_paid, 0)
        - COALESCE(discounts.total_discount, 0)
        - COALESCE(scholarships.total_scholarship, 0)
    )::BIGINT AS outstanding
FROM users u
JOIN students s ON s.student_id = u.id
JOIN (
    SELECT student_id, SUM(fee_at_enrollment) AS total_fee
    FROM student_courses
    GROUP BY student_id
) fees ON fees.student_id = s.id
LEFT JOIN (
    SELECT student_id, SUM(amount) AS total_paid
    FROM payments
    GROUP BY student_id
) pays ON pays.student_id = s.id
LEFT JOIN (
    SELECT student_id, SUM(amount) AS total_discount
    FROM student_discounts
    GROUP BY student_id
) discounts ON discounts.student_id = s.id
LEFT JOIN (
    SELECT student_id, SUM(amount) AS total_scholarship
    FROM student_scholarships
    GROUP BY student_id
) scholarships ON scholarships.student_id = s.id
WHERE s.status IN ('active', 'completed')
  AND (
        COALESCE(fees.total_fee, 0)
        - COALESCE(pays.total_paid, 0)
        - COALESCE(discounts.total_discount, 0)
        - COALESCE(scholarships.total_scholarship, 0)
      ) > 0
  AND ($3::TEXT IS NULL OR s.created_at >= $3::TIMESTAMPTZ)
  AND ($4::TEXT IS NULL OR s.created_at <= ($4::TIMESTAMPTZ + INTERVAL '1 day'))
  AND ($5::TEXT IS NULL OR u.name ILIKE '%' || $5::TEXT || '%' OR u.email ILIKE '%' || $5::TEXT || '%')
ORDER BY outstanding DESC
LIMIT $1 OFFSET $2
`

type GetStudentsWithOutstandingFeesParams struct {
	Limit    int32       `json:"limit"`
	Offset   int32       `json:"offset"`
	FromDate pgtype.Text `json:"fromDate"`
	ToDate   pgtype.Text `json:"toDate"`
	Search   pgtype.Text `json:"search"`
}

type GetStudentsWithOutstandingFeesRow struct {
	UserID           pgtype.UUID `json:"userId"`
	StudentID        pgtype.UUID `json:"studentId"`
	Name             string      `json:"name"`
	Email            string      `json:"email"`
	TotalCourseFee   int64       `json:"totalCourseFee"`
	TotalPaid        int64       `json:"totalPaid"`
	TotalDiscount    int64       `json:"totalDiscount"`
	TotalScholarship int64       `json:"totalScholarship"`
	Outstanding      int64       `json:"outstanding"`
}

func (q *Queries) GetStudentsWithOutstandingFees(ctx context.Context, arg GetStudentsWithOutstandingFeesParams) ([]GetStudentsWithOutstandingFeesRow, error) {
	rows, err := q.db.Query(ctx, getStudentsWithOutstandingFees,
		arg.Limit,
		arg.Offset,
		arg.FromDate,
		arg.ToDate,
		arg.Search,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []GetStudentsWithOutstandingFeesRow
	for rows.Next() {
		var i GetStudentsWithOutstandingFeesRow
		if err := rows.Scan(
			&i.UserID,
			&i.StudentID,
			&i.Name,
			&i.Email,
			&i.TotalCourseFee,
			&i.TotalPaid,
			&i.TotalDiscount,
			&i.TotalScholarship,
			&i.Outstanding,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listStudents = `-- name: ListStudents :many
SELECT 
    s.id,
    s.reference_no,
    s.full_name,
    s.phone,
    s.status,
    s.created_at,
    s.batch,
    s.shift,
    COALESCE(
        STRING_AGG(c.name, ',' ORDER BY c.name),
        ''
    ) AS courses
FROM students s
LEFT JOIN student_courses sc ON sc.student_id = s.id
LEFT JOIN courses c ON c.id = sc.course_id
WHERE
    ($3::text = '' OR s.status = $3::text)
    AND ($4::text = '' OR s.shift = $4::text)
    AND ($5::text = '' OR s.batch = $5::text)
    AND ($6::text = '' OR c.name ILIKE $6::text)
    AND (
        $7::text = ''
        OR s.full_name ILIKE '%' || $7 || '%'
        OR s.reference_no ILIKE '%' || $7 || '%'
        OR s.phone ILIKE '%' || $7 || '%'
    )
GROUP BY s.id
ORDER BY s.created_at DESC
LIMIT $1 OFFSET $2
`

type ListStudentsParams struct {
	Limit  int32  `json:"limit"`
	Offset int32  `json:"offset"`
	Status string `json:"status"`
	Shift  string `json:"shift"`
	Batch  string `json:"batch"`
	Course string `json:"course"`
	Search string `json:"search"`
}

type ListStudentsRow struct {
	ID          pgtype.UUID        `json:"id"`
	ReferenceNo string             `json:"referenceNo"`
	FullName    string             `json:"fullName"`
	Phone       string             `json:"phone"`
	Status      string             `json:"status"`
	CreatedAt   pgtype.Timestamptz `json:"createdAt"`
	Batch       pgtype.Text        `json:"batch"`
	Shift       string             `json:"shift"`
	Courses     interface{}        `json:"courses"`
}

func (q *Queries) ListStudents(ctx context.Context, arg ListStudentsParams) ([]ListStudentsRow, error) {
	rows, err := q.db.Query(ctx, listStudents,
		arg.Limit,
		arg.Offset,
		arg.Status,
		arg.Shift,
		arg.Batch,
		arg.Course,
		arg.Search,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListStudentsRow
	for rows.Next() {
		var i ListStudentsRow
		if err := rows.Scan(
			&i.ID,
			&i.ReferenceNo,
			&i.FullName,
			&i.Phone,
			&i.Status,
			&i.CreatedAt,
			&i.Batch,
			&i.Shift,
			&i.Courses,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

